// Existing Actions/private-bus HTTP suite, no live SDK or injected receipt.
fn org_relation_http_config(root:&str)->serde_json::Value{let mut v=im_runtime_config_json(root);v["profile"]["org_relation_sync"]=serde_json::json!({"receive":true});v}
#[tokio::test]async fn org_relation_http_auth_finite_readonly_query_cannot_mint_receipt_or_clear_write(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/org-relation-events";let(status,_,body)=account_request(&served,reqwest::Method::GET,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;for suffix in ["?limit=0","?limit=129","?limit=1&uid=private","?limit=1&clear_unknown=true","?limit=1&write=true"]{let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("{path}{suffix}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}for method in [reqwest::Method::POST,reqwest::Method::DELETE]{let(status,_,_)=account_request(&served,method,path,Some(serde_json::json!({"accepted":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::METHOD_NOT_ALLOWED);}assert!(state.app.app_accounts.list(100).await.unwrap().is_empty());}
#[tokio::test]async fn org_relation_http_policy_requires_original_common_clientex_im_and_never_enables_directory_or_write(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let good=org_relation_http_config(&cert.root);for mutation in [serde_json::json!({"client_ex":false}),serde_json::json!({"native_receivers":{}}),serde_json::json!({"org_relation_sync":{"receive":false}}),serde_json::json!({"org_relation_sync":{"receive":true,"write":true}})]{let mut c=good.clone();for(k,v)in mutation.as_object().unwrap(){c["profile"][k]=v.clone();}let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":c})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":good})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(!view.outbound_authorized&&!view.incoming_call_ready&&!view.incoming_message_ready);let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/org-relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));}
#[tokio::test]async fn org_relation_http_stored_control_is_redacted_not_chat_or_full_roster_or_unknown_write_result(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":org_relation_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
 state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_org_relation_messages(line_id,revision,identity_key,message_index,fingerprint,body,receipt_epoch,group_hash,label_hash,base_time,update_time,relation_type,org_deleted,relation_supplied,continuity,created_at) VALUES(?1,1,zeroblob(32),?2,zeroblob(32),?3,?4,zeroblob(32),zeroblob(32),NULL,?5,20,1,0,'unsequenced','2026-01-01T00:00:00Z')",rusqlite::params![line,i64::MIN,b"private-system-body".as_slice(),"a".repeat(32),i64::MAX]).map_err(|_|"fixture data only")).unwrap();
 let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/org-relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);let json:serde_json::Value=serde_json::from_str(&body).unwrap();let row=&json["data"][0];assert_eq!(row.as_object().unwrap().len(),10);assert_eq!(row["message_index"],"-9223372036854775808");assert!(row["base_time"].is_null());assert_eq!(row["update_time"],"9223372036854775807");assert_eq!(row["removal"],true);assert_eq!(row["org_deleted"],true);assert_eq!(row["relation_supplied"],false);assert_eq!(row["full_roster_verified"],false);for private in ["private-system-body","identity_key","label_hash","group_hash","receipt_epoch","token","nonce"]{assert!(!body.contains(private));}
 assert!(state.app.app_accounts.im_messages(&line,128).unwrap().is_empty());assert!(state.app.app_accounts.relation_write_history(&line,128).unwrap().is_empty());assert_eq!(state.app.app_accounts.get(&line,100).await.unwrap().phase,"stopped");}
#[tokio::test]async fn org_relation_http_corrupt_observation_rejects_without_exposing_private_text(){let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":org_relation_http_config(&cert.root)})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);state.app.database.with_conn(|c|c.execute("INSERT INTO app_voice_org_relation_messages(line_id,revision,identity_key,message_index,fingerprint,body,receipt_epoch,group_hash,label_hash,relation_type,org_deleted,relation_supplied,continuity,created_at) VALUES(?1,1,zeroblob(32),1,zeroblob(32),X'',?2,zeroblob(32),zeroblob(32),20,0,0,'unsequenced',?3)",rusqlite::params![line,"a".repeat(32),"private-invalid-time".repeat(128)]).map_err(|_|"fixture")).unwrap();let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/org-relation-events?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::INTERNAL_SERVER_ERROR);no_store(&headers);no_secrets(&body);assert!(!body.contains("private-invalid-time"));}
